def selection(population, fitnesses, n_select, _errors=None, _penalized=None):
    """Pareto-lexicase selection: pre-filter by parsimony fitness,
    then epsilon-lexicase on per-case errors."""
    selected = []
    pop_size = len(population)
    if _errors is None:
        for _ in range(n_select):
            cands = random.sample(range(pop_size), min(7, pop_size))
            best = min(cands, key=lambda i: fitnesses[i])
            selected.append(population[best].copy())
        return selected
