            mad = float(np.median(np.abs(ce - med)))
            cutoff = float(np.min(ce)) + mad
            cands = [c for c, e in zip(cands, ce) if e <= cutoff]
        winner = random.choice(cands)
        selected.append(population[winner].copy())
    return selected


